using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using EngineeringWorkspace.Application.Catalog;

namespace EngineeringWorkspace.Infrastructure.Catalog;

/// <summary>
/// Loads the catalog generated by build/scripts/catalog/generate_catalog.py and embedded as catalog.json.gz. The
/// catalog is available from the first start, without a database or network.
/// </summary>
public sealed class EmbeddedCatalogService : ICatalogService
{
    public const string ResourceName = "EngineeringWorkspace.Catalog.catalog.json.gz";
    private readonly Lazy<ControlCatalog> _catalog = new(Load, LazyThreadSafetyMode.ExecutionAndPublication);

    public ControlCatalog Catalog => _catalog.Value;

    private sealed record ExpectationDto(string Path, JsonElement Value);

    private sealed record ControlDto(
        string Id, string? Number, string Kind, string? Category, string? Platform, string Name, string? Setting, string? Value, string? Description,
        string? Source, List<string>? Frameworks, string? Severity, string? UserImpact, string? Experience, string? PainPoints, string? Licensing,
        string? GraphResource, string? OdataType, string? TemplateFamily, string Evaluation, List<ExpectationDto>? Expected, string? Path,
        List<string>? PolicySets, Dictionary<string, string>? Attributes, string? Body, string? SolutionArea, string? ExperienceArea, string? VariantOf,
        string? VariantLabel, ImplementationDto? Implementation, Dictionary<string, string>? Remediation, List<string>? Generated,
        string? Product = null, string? FeatureArea = null, string? DefaultValue = null, string? AssessMethod = null, string? DeployMethod = null,
        string? SourceVersion = null, string? SourceUrl = null);

    private sealed record ImplementationDto(int EstimatedMinutes, string? Difficulty, string? Effort, string? RiskLevel, string? Benefits, string? ExperienceImpact);

    private sealed record ReferenceDto(string Code, string? Name, string? Description);

    private sealed record SpecificationDto(string Code, string? Name, string? Description, List<string>? PolicySets, List<string>? ControlIds, List<string>? Experiences,
        List<string>? Frameworks);

    private sealed record BaselineDto(string Code, string? Name, string? Description, bool IsActive, List<string>? PolicySets, List<string>? ControlIds);

    private sealed record AliasDto(string Alias, string ControlId, string? SourcePath, string? Reason);

    private sealed record PolicySetDto(string Id, string? DisplayName, string? Description, int DeploymentOrder, List<string>? Requires, List<string>? Includes, List<string>? ControlIds);

    private sealed record CatalogDto(string? Source, string? GeneratedAtUtc, string? DerivedFieldsNote, List<PolicySetDto>? PolicySets, List<ControlDto>? Controls,
        string? SeedVersion, List<ReferenceDto>? SolutionAreas, List<ReferenceDto>? ExperienceAreas, List<SpecificationDto>? Specifications,
        List<BaselineDto>? Baselines, List<AliasDto>? Aliases);

    public static ControlCatalog Load()
    {
        using var stream = typeof(EmbeddedCatalogService).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"The embedded control catalog {ResourceName} is missing from the build.");
        return Load(stream);
    }

    public static ControlCatalog Load(Stream compressed)
    {
        using var buffer = new MemoryStream();
        compressed.CopyTo(buffer);
        var hash = Convert.ToHexString(SHA256.HashData(buffer.GetBuffer().AsSpan(0, (int)buffer.Length))).ToLowerInvariant();
        buffer.Position = 0;
        using var gzip = new GZipStream(buffer, CompressionMode.Decompress);
        var dto = JsonSerializer.Deserialize<CatalogDto>(gzip, new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
                  ?? throw new InvalidDataException("The control catalog is empty.");
        var sets = (dto.PolicySets ?? []).Select(set => new CatalogPolicySet(set.Id, set.DisplayName ?? set.Id, set.Description ?? string.Empty, set.DeploymentOrder,
            set.Requires ?? [], set.Includes ?? [], set.ControlIds ?? [])).ToArray();
        var controls = (dto.Controls ?? []).Select(control => new CatalogControl(
            control.Id, control.Number ?? string.Empty, control.Kind, control.Category ?? string.Empty, control.Platform ?? string.Empty, control.Name,
            control.Setting ?? string.Empty, control.Value ?? string.Empty, control.Description ?? string.Empty, control.Source ?? string.Empty,
            control.Frameworks ?? [], control.Severity ?? "Medium", control.UserImpact ?? string.Empty, control.Experience ?? string.Empty,
            control.PainPoints ?? string.Empty, control.Licensing ?? string.Empty, control.GraphResource ?? string.Empty, control.OdataType ?? string.Empty,
            control.TemplateFamily ?? string.Empty, control.Evaluation,
            (control.Expected ?? []).Select(item => new CatalogExpectation(item.Path, item.Value.Clone())).ToArray(),
            control.Path ?? string.Empty, control.PolicySets ?? [],
            control.Attributes ?? new Dictionary<string, string>(), control.Body ?? string.Empty)
        {
            SolutionArea = control.SolutionArea ?? string.Empty,
            ExperienceArea = control.ExperienceArea ?? string.Empty,
            VariantOf = control.VariantOf ?? string.Empty,
            VariantLabel = control.VariantLabel ?? string.Empty,
            Implementation = control.Implementation is { } implementation
                ? new ControlImplementation(implementation.EstimatedMinutes, implementation.Difficulty ?? string.Empty, implementation.Effort ?? string.Empty,
                    implementation.RiskLevel ?? string.Empty, implementation.Benefits ?? string.Empty, implementation.ExperienceImpact ?? string.Empty)
                : ControlImplementation.Empty,
            Remediation = Remediation(control.Remediation),
            Generated = control.Generated ?? [],
            Product = control.Product ?? string.Empty,
            FeatureArea = control.FeatureArea ?? string.Empty,
            DefaultValue = control.DefaultValue ?? string.Empty,
            AssessMethodOverride = control.AssessMethod ?? string.Empty,
            DeployMethodOverride = control.DeployMethod ?? string.Empty,
            SourceVersion = control.SourceVersion ?? string.Empty,
            SourceUrl = control.SourceUrl ?? string.Empty
        }).ToArray();
        static CatalogReferenceValue Reference(ReferenceDto item) => new(item.Code, item.Name ?? item.Code, item.Description ?? string.Empty);
        return new ControlCatalog(dto.Source ?? "unknown", dto.GeneratedAtUtc ?? string.Empty, dto.DerivedFieldsNote ?? string.Empty, sets, controls,
            (dto.Aliases ?? []).Select(alias => new CatalogAlias(alias.Alias, alias.ControlId, alias.SourcePath ?? string.Empty, alias.Reason ?? string.Empty)).ToArray())
        {
            ContentHash = hash,
            SeedVersion = dto.SeedVersion ?? "1",
            SolutionAreas = (dto.SolutionAreas ?? []).Select(Reference).ToArray(),
            ExperienceAreas = (dto.ExperienceAreas ?? []).Select(Reference).ToArray(),
            Specifications = (dto.Specifications ?? []).Select(spec => new CatalogSpecification(spec.Code, spec.Name ?? spec.Code, spec.Description ?? string.Empty,
                spec.PolicySets ?? [], spec.ControlIds ?? [], spec.Experiences ?? [], spec.Frameworks ?? [])).ToArray(),
            Baselines = (dto.Baselines ?? []).Select(baseline => new CatalogBaseline(baseline.Code, baseline.Name ?? baseline.Code, baseline.Description ?? string.Empty,
                baseline.IsActive, baseline.PolicySets ?? [], baseline.ControlIds ?? [])).ToArray()
        };
    }

    private static ControlRemediation Remediation(Dictionary<string, string>? values)
    {
        if (values is null || values.Count == 0) return ControlRemediation.Empty;
        string Get(string key) => values.TryGetValue(key, out var value) ? value : string.Empty;
        return new ControlRemediation(Get("graphRequest"), Get("graphCommand"), Get("powerShell"), Get("jsonBody"), Get("settingPath"), Get("gpoPath"), Get("registry"),
            Get("steps"), Get("deploymentMethod"), Get("validation"), Get("rollback"), Get("evidence"));
    }
}
